DELIMITER $$
CREATE TRIGGER `lock_platform_before_insert` BEFORE INSERT ON `services` FOR EACH ROW BEGIN
    IF NEW.category LIKE '%tiktok%' THEN
        SET NEW.platform = 'tiktok';
