        SET NEW.platform = 'instagram';
    ELSEIF NEW.category LIKE '%facebook%' THEN
        SET NEW.platform = 'facebook';
    ELSEIF NEW.category LIKE '%youtube%' THEN
        SET NEW.platform = 'youtube';
    ELSEIF NEW.category LIKE '%spotify%' THEN
        SET NEW.platform = 'spotify';
    ELSEIF NEW.category LIKE '%linkedin%' THEN
        SET NEW.platform = 'linkedin';
    ELSEIF NEW.category LIKE '%telegram%' THEN
        SET NEW.platform = 'telegram';
    ELSEIF NEW.category LIKE '%whatsapp%' THEN
        SET NEW.platform = 'whatsapp';
    ELSEIF NEW.category LIKE '%twitter%' THEN
        SET NEW.platform = 'twitter';
    ELSEIF NEW.category LIKE '%website%' THEN
        SET NEW.platform = 'website';
    ELSEIF NEW.category LIKE '%other%' THEN
        SET NEW.platform = 'other';
    END IF;
END
$$
DELIMITER ;
