INSERT INTO `settings` (`id`, `site_url`, `header_code`, `footer_code`, `manual_payment_instructions`, `currency_symbol`, `currency_code`, `logo`) VALUES
(1, 'https://yourdomain.com', '', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<title>WhatsApp Footer Contact</title>\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n\r\n<!-- Font Awesome -->\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css\">\r\n\r\n<style>\r\n/* =========================\r\n   WhatsApp Floating Button\r\n   ========================= */\r\n.whatsapp-footer {\r\n  position: fixed;\r\n  bottom: 20px;\r\n  right: 20px;\r\n  z-index: 9999;\r\n}\r\n\r\n.whatsapp-footer a {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  background: #25D366;\r\n  color: #ffffff;\r\n  padding: 14px 20px;\r\n  border-radius: 50px;\r\n  text-decoration: none;\r\n  font-family: Arial, sans-serif;\r\n  font-size: 15px;\r\n  font-weight: bold;\r\n  box-shadow: 0 8px 20px rgba(0,0,0,0.25);\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.whatsapp-footer a:hover {\r\n  transform: scale(1.07);\r\n  box-shadow: 0 12px 30px rgba(0,0,0,0.35);\r\n}\r\n\r\n.whatsapp-footer i {\r\n  font-size: 24px;\r\n}\r\n\r\n/* Mobile optimization */\r\n@media (max-width: 600px) {\r\n  .whatsapp-footer a span {\r\n    display: none;\r\n  }\r\n  .whatsapp-footer a {\r\n    padding: 15px;\r\n    border-radius: 50%;\r\n  }\r\n}\r\n</style>\r\n</head>\r\n\r\n<body>\r\n\r\n<!-- WhatsApp Button -->\r\n<div class=\"whatsapp-footer\">\r\n  <a href=\"#\" id=\"whatsappBtn\">\r\n    <i class=\"fab fa-whatsapp\"></i>\r\n    <span>Chat on WhatsApp</span>\r\n  </a>\r\n</div>\r\n\r\n<script>\r\n/* =========================\r\n   WhatsApp Click Action\r\n   ========================= */\r\ndocument.getElementById(\"whatsappBtn\").addEventListener(\"click\", function (e) {\r\n  e.preventDefault();\r\n\r\n  const phone = \"243814696807\";\r\n  const message = \"Hello I have issue with Cheap Panel\";\r\n  const encodedMessage = encodeURIComponent(message);\r\n\r\n  const whatsappURL = \"https://wa.me/\" + phone + \"?text=\" + encodedMessage;\r\n  window.open(whatsappURL, \"_blank\");\r\n});\r\n</script>\r\n\r\n</body>\r\n</html>', 'PAYMENT METHODS \r\n\r\nVODACOM M-PESA\r\n0814696807\r\nMoroma Salomon \r\n\r\nORANGE MONEY ? \r\n0800165466\r\nSamuel Lomonobo\r\n\r\nAIRTEL MONEY \r\n0986357453\r\nAyikoru Asera', '$', 'USD', 'uploads/logo/site-logo.jpg');
